import {
  forwardRef,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";

import { useReducedMotion } from "./hooks/use-reduced-motion";
import { ensureMotionStyles } from "./styles";

/** Default glyph — the terminal block cursor. */
const DEFAULT_CHAR = "▌";

/**
 * Applies the shared caret styling to an element — used by the
 * `Caret` component and by primitives that insert a caret via DOM
 * APIs (Typewriter's trailing cursor), so the blink stays one source.
 */
export function applyCaretStyles(el: HTMLElement, interval: number): void {
  el.style.display = "inline-block";
  el.style.color = "var(--accent, currentColor)";
  el.style.animation = `ionbit-ui-caret-blink ${interval}ms step-end infinite`;
}

export interface CaretProps extends HTMLAttributes<HTMLSpanElement> {
  /** Glyph to blink. @default "▌" */
  children?: ReactNode;
  /** Blink on/off — when false the glyph renders static. @default true */
  blink?: boolean;
  /** Blink cycle in ms. @default 1100 */
  interval?: number;
}

/**
 * Caret — a blinking terminal block cursor as a standalone primitive.
 * Place it after prompts, inputs, or status lines that read as "the
 * channel is open". The same caret Typewriter trails while typing.
 *
 * Reduced motion: renders the glyph statically — a blinking cursor is
 * decoration, not content.
 */
export const Caret = forwardRef<HTMLSpanElement, CaretProps>(function Caret(
  { children = DEFAULT_CHAR, blink = true, interval = 1100, style, ...rest },
  ref,
) {
  const reduced = useReducedMotion();

  ensureMotionStyles();

  const caretStyle: CSSProperties = { display: "inline-block" };
  if (blink && !reduced) {
    caretStyle.color = "var(--accent, currentColor)";
    caretStyle.animation = `ionbit-ui-caret-blink ${interval}ms step-end infinite`;
  }

  return (
    <span
      ref={ref}
      aria-hidden="true"
      data-caret=""
      style={{ ...caretStyle, ...style }}
      {...rest}
    >
      {children}
    </span>
  );
});

import { useEffect, useState } from "react";

/**
 * Returns `true` when the user has requested reduced motion via the OS / browser.
 *
 * All Ionbit UI motion primitives use this to self-disable. Components should
 * never animate transform/opacity in a way that distracts under reduced motion.
 */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState<boolean>(() => {
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  });

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const handler = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  return reduced;
}

// Single global <style> tag for all motion primitives.
// Injected once on first use; subsequent calls are no-ops.

const STYLES = `
/* Reveal — toggled via data-revealed attribute by IntersectionObserver. */
[data-digital-reveal][data-revealed="true"] {
  opacity: 1 !important;
  transform: none !important;
}

/* Glow — hover/focus/always-driven box-shadow or text-shadow.
   Triggers are controlled via data-glow-hover, data-glow-focus and
   data-glow-always; the shadow value is set as a CSS custom property
   on the element. Hover triggering is gated behind (hover: hover) —
   on touch devices :hover sticks after a tap, so the glow would
   latch on until the next tap elsewhere. */
@media (hover: hover) {
  [data-digital-glow][data-glow-hover="true"][data-glow-variant="halo"]:hover {
    box-shadow: var(--glow-shadow);
  }

  [data-digital-glow][data-glow-hover="true"][data-glow-variant="text"]:hover {
    text-shadow: var(--glow-text-shadow);
  }
}

[data-digital-glow][data-glow-focus="true"][data-glow-variant="halo"]:focus-within,
[data-digital-glow][data-glow-always="true"][data-glow-variant="halo"] {
  box-shadow: var(--glow-shadow);
}

[data-digital-glow][data-glow-focus="true"][data-glow-variant="text"]:focus-within,
[data-digital-glow][data-glow-always="true"][data-glow-variant="text"] {
  text-shadow: var(--glow-text-shadow);
}

/* When the wrapped control presses down on :active (e.g. Button's
   translate-y-px), move the whole unit — element + halo — together:
   the wrapper takes over the 1px shift and the child's own active
   translate/transform is neutralized so it doesn't apply twice.
   Scoped to interactive controls — :active also matches static
   elements (browsers apply it to the pressed element's ancestors),
   so without the :is() guard a wrapped div would shift too. */
[data-digital-glow]:has(> :is(button, a, [role="button"]):active) {
  translate: 0 1px;
}
[data-digital-glow][data-glow-variant]
  > :is(button, a, [role="button"]):active {
  translate: none;
  transform: none;
}

/* Pulse — single shared keyframes; intensity controlled via CSS vars. */
@keyframes ionbit-ui-pulse-halo {
  0%, 100% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--pulse-color) 0%, transparent);
  }
  50% {
    box-shadow: 0 0 var(--pulse-blur) var(--pulse-spread)
      color-mix(in oklab, var(--pulse-color) var(--pulse-alpha), transparent);
  }
}

@keyframes ionbit-ui-pulse-text {
  0%, 100% {
    text-shadow: 0 0 0 color-mix(in oklab, var(--pulse-color) 0%, transparent);
  }
  50% {
    text-shadow: 0 0 var(--pulse-blur)
      color-mix(in oklab, var(--pulse-color) var(--pulse-alpha), transparent);
  }
}

/* Ripple — circle expands from the press point to cover the element,
   then fades out. Peak opacity is set per-instance via --ripple-opacity.
   The span is removed on animationend. */
@keyframes ionbit-ui-ripple {
  0% {
    transform: scale(0);
    opacity: var(--ripple-opacity, 0.24);
  }
  60% {
    transform: scale(1);
    opacity: var(--ripple-opacity, 0.24);
  }
  100% {
    transform: scale(1);
    opacity: 0;
  }
}

/* Trace — an accent beam travels along the element's border. The beam
   overlay paints a conic-gradient masked to the border ring; rotating
   --ionbit-trace-angle moves the bright segment around the perimeter.
   @property registration is required for the angle to interpolate —
   browsers without it get a static beam (graceful degradation). */
@property --ionbit-trace-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@keyframes ionbit-ui-trace {
  to {
    --ionbit-trace-angle: 1turn;
  }
}

/* Typewriter / Caret — the block caret blinks like a terminal cursor. */
@keyframes ionbit-ui-caret-blink {
  0%, 55% {
    opacity: 1;
  }
  56%, 100% {
    opacity: 0;
  }
}

/* Marquee — the track holds enough measured copies to cover the
   viewport while one slides out; each cycle shifts exactly one copy
   width (--marquee-shift, -50% before measurement). The animation is
   declared HERE, not inline — an inline animation shorthand would
   override this rule's animation-play-state, which is exactly what
   pauseOnHover needs. Direction/duration come in as CSS vars.
   Pause is gated behind (hover: hover) so a tap doesn't latch it. */
@keyframes ionbit-ui-marquee {
  to {
    transform: translateX(var(--marquee-shift, -50%));
  }
}

[data-marquee-track] {
  animation: ionbit-ui-marquee var(--marquee-duration, 24s) linear
    infinite;
  animation-direction: var(--marquee-direction, normal);
}

@media (hover: hover) {
  [data-marquee][data-pause-on-hover]:hover [data-marquee-track],
  [data-marquee-pause-scope]:hover
    [data-marquee][data-pause-on-hover]
    [data-marquee-track] {
    animation-play-state: paused;
  }
}

/* SplitFlap — optional card chrome (the cards prop). One merged
   card face around the whole module block: the strip itself is the
   card and the glyphs inside are plain text, so nothing misaligns,
   and the fill is identical at rest and mid-pass — edge pad modules
   are covered too since the background lives on the element, not on
   per-char boxes. Leaves share the card fill so a falling leaf
   reads as the strip's own face. */
[data-splitflap-cards] {
  display: inline-block;
  background: var(
    --splitflap-card-bg,
    color-mix(in oklab, currentColor 9%, transparent)
  );
}

[data-splitflap-cards] [data-splitflap-flap-top],
[data-splitflap-cards] [data-splitflap-flap-bottom] {
  background: var(
    --splitflap-card-bg,
    color-mix(in oklab, currentColor 9%, transparent)
  );
}
`;

let injected = false;

export function ensureMotionStyles(): void {
  if (injected || typeof document === "undefined") return;
  const existing = document.getElementById("ionbit-ui-motion-styles");
  if (existing) {
    // Refresh stale content — after HMR the module-level `injected` flag
    // resets but the old <style> tag persists with outdated rules.
    if (existing.textContent !== STYLES) existing.textContent = STYLES;
    injected = true;
    return;
  }
  const el = document.createElement("style");
  el.id = "ionbit-ui-motion-styles";
  el.textContent = STYLES;
  document.head.appendChild(el);
  injected = true;
}
